import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

namespace cute_matmul_detail {

constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 16;
constexpr int THREADS = 256;
constexpr int RM = 8;
constexpr int RN = 8;

__global__ void cute_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int N,
    int K)
{
    extern __shared__ float smem[];
    float* smem_A = smem;
    float* smem_B = smem + BM * BK;

    auto gA = make_tensor(
        make_gmem_ptr(A),
        make_shape(M, K),
        make_stride(K, Int<1>{}));

    auto gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(K, N),
        make_stride(N, Int<1>{}));

    auto gC = make_tensor(
        make_gmem_ptr(C),
        make_shape(M, N),
        make_stride(N, Int<1>{}));

    auto sA = make_tensor(
        make_smem_ptr(smem_A),
        make_shape(Int<BM>{}, Int<BK>{}),
        make_stride(Int<BK>{}, Int<1>{}));

    auto sB = make_tensor(
        make_smem_ptr(smem_B),
        make_shape(Int<BK>{}, Int<BN>{}),
        make_stride(Int<BN>{}, Int<1>{}));

    int tid = threadIdx.x;
    int block_m = blockIdx.y * BM;
    int block_n = blockIdx.x * BN;

    int warp_row = (tid / 16) * RM;
    int warp_col = (tid % 16) * RN;

    float accum[RM][RN];

    #pragma unroll
    for (int i = 0; i < RM; ++i) {
        #pragma unroll
        for (int j = 0; j < RN; ++j) {
            accum[i][j] = 0.0f;
        }
    }

    const bool can_vec_A =
        (reinterpret_cast<uintptr_t>(A) & 0xF) == 0 &&
        (K % 4 == 0);
    const bool can_vec_B =
        (reinterpret_cast<uintptr_t>(B) & 0xF) == 0 &&
        (N % 4 == 0);
    for (int k_base = 0; k_base < K; k_base += BK) {
        for (int linear = tid * 4;
             linear < BM * BK;
             linear += THREADS * 4) {
            int row = linear / BK;
            int col = linear % BK;
            int gm = block_m + row;
            int gk = k_base + col;
            if (can_vec_A &&
                linear + 3 < BM * BK &&
                col + 3 < BK &&
                gm < M &&
                gk + 3 < K) {
                float4 v =
                    *reinterpret_cast<const float4*>(A + gm * K + gk);
                sA(row, col + 0) = v.x;
                sA(row, col + 1) = v.y;
                sA(row, col + 2) = v.z;
                sA(row, col + 3) = v.w;
            } else {
                #pragma unroll
                for (int x = 0; x < 4; ++x) {
                    int local_col = col + x;
                    if (local_col < BK) {
                        int kk = k_base + local_col;
                        sA(row, local_col) =
                            (gm < M && kk < K) ? gA(gm, kk) : 0.0f;
                    }
                }
            }
        }
        for (int linear = tid * 4;
             linear < BK * BN;
             linear += THREADS * 4) {
            int row = linear / BN;
            int col = linear % BN;
            int gk = k_base + row;
            int gn = block_n + col;
            if (can_vec_B &&
                linear + 3 < BK * BN &&
                col + 3 < BN &&
                gk < K &&
                gn + 3 < N) {
                float4 v =
                    *reinterpret_cast<const float4*>(B + gk * N + gn);
                sB(row, col + 0) = v.x;
                sB(row, col + 1) = v.y;
                sB(row, col + 2) = v.z;
                sB(row, col + 3) = v.w;
            } else {
                #pragma unroll
                for (int x = 0; x < 4; ++x) {
                    int local_col = col + x;
                    if (local_col < BN) {
                        int nn = block_n + local_col;
                        sB(row, local_col) =
                            (gk < K && nn < N) ? gB(gk, nn) : 0.0f;
                    }
                }
            }
        }
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float a_frag[RM];
            float b_frag[RN];
            #pragma unroll
            for (int i = 0; i < RM; ++i) {
                a_frag[i] = sA(warp_row + i, kk);
            }
            #pragma unroll
            for (int j = 0; j < RN; ++j) {
                b_frag[j] = sB(kk, warp_col + j);
            }
            #pragma unroll
            for (int i = 0; i < RM; ++i) {
                #pragma unroll
                for (int j = 0; j < RN; ++j) {
                    accum[i][j] += a_frag[i] * b_frag[j];
                }
            }
        }
        __syncthreads();
    }

    #pragma unroll
    for (int i = 0; i < RM; ++i) {
        int m = block_m + warp_row + i;
        if (m < M) {
            #pragma unroll
            for (int j = 0; j < RN; ++j) {
                int n = block_n + warp_col + j;
                if (n < N) {
                    gC(m, n) = accum[i][j];
                }
            }
        }
    }
}

}  // namespace cute_matmul_detail

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must be 2-dimensional");
    TORCH_CHECK(B.dim() == 2, "B must be 2-dimensional");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");

    const int M = static_cast<int>(A.size(0));
    const int K = static_cast<int>(A.size(1));
    const int K_B = static_cast<int>(B.size(0));
    const int N = static_cast<int>(B.size(1));

    TORCH_CHECK(K == K_B, "Incompatible matrix dimensions");

    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();
    auto C = torch::empty({M, N}, A.options());

    dim3 block(cute_matmul_detail::THREADS);
    dim3 grid(
        (N + cute_matmul_detail::BN - 1) / cute_matmul_detail::BN,
        (M + cute_matmul_detail::BM - 1) / cute_matmul_detail::BM);

    constexpr size_t shared_bytes =
        (cute_matmul_detail::BM * cute_matmul_detail::BK +
         cute_matmul_detail::BK * cute_matmul_detail::BN) * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_matmul_detail::cute_matmul_kernel<<<grid, block, shared_bytes, stream>>> (
        A_contig.data_ptr<float>(),
        B_contig.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        N,
        K);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE matrix multiplication kernel launch failed");

    return C;
}
"""


cute_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=[
        "-O3",
        "-std=c++17",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-std=c++17",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A, B)

